{
  "action": "plan",
  "reason": "建立取证分工：数值要求以 query 绑定精确 QueryPlan；原文/表格核对以 source_evidence 绑定 googl-2025-10k；准备将 capex 数值、期间、口径核对委派给 Worker，Worker 返回后宿主自行独立核验。完成条件：每个要求均有证据或明确缺口；不推导自由现金流、维护性资本开支或 AI 投资回报。",
  "requirements": [
    {
      "requirement_id": "req-q-ocf-2024-2025",
      "kind": "query",
      "description": "查询 Alphabet 合并经营现金流 operating_cash_flow 在 2024 年和 2025 年的实际值，保留单位、期间和合并口径。",
      "query": {
        "records": [
          {
            "entity_id": "sec-0001652044",
            "metric_id": "operating_cash_flow",
            "period": {
              "kind": "year",
              "start": "2024-01-01",
              "end": "2024-12-31"
            }
          },
          {
            "entity_id": "sec-0001652044",
            "metric_id": "operating_cash_flow",
            "period": {
              "kind": "year",
              "start": "2025-01-01",
              "end": "2025-12-31"
            }
          }
        ]
      }
    },
    {
      "requirement_id": "req-q-capex-2024-2025",
      "kind": "query",
      "description": "查询 Alphabet 购建固定资产的现金支出 capex_cash_payments 在 2024 年和 2025 年的实际值，保留单位、期间和合并口径；此数值核对任务准备委派给 Worker。",
      "query": {
        "records": [
          {
            "entity_id": "sec-0001652044",
            "metric_id": "capex_cash_payments",
            "period": {
              "kind": "year",
              "start": "2024-01-01",
              "end": "2024-12-31"
            }
          },
          {
            "entity_id": "sec-0001652044",
            "metric_id": "capex_cash_payments",
            "period": {
              "kind": "year",
              "start": "2025-01-01",
              "end": "2025-12-31"
            }
          }
        ]
      }
    },
    {
      "requirement_id": "req-ev-ocf-verification",
      "kind": "source_evidence",
      "source_id": "googl-2025-10k",
      "description": "读取 Alphabet FY2025 10-K 合并现金流量表及相邻必要说明，独立核验 2024 年和 2025 年合并经营现金流原始披露，保留精确原文、单位、期间和会计口径。"
    },
    {
      "requirement_id": "req-ev-capex-verification",
      "kind": "source_evidence",
      "source_id": "googl-2025-10k",
      "description": "读取 Alphabet FY2025 10-K 中购建固定资产现金支出的现金流量表行项目及相邻必要说明，独立核验 2024 年和 2025 年原始披露，保留精确原文、单位、期间和会计口径；Worker 返回后由宿主自行复核。"
    },
    {
      "requirement_id": "req-ev-capex-uses-actual",
      "kind": "source_evidence",
      "source_id": "googl-2025-10k",
      "description": "定位 Alphabet FY2025 10-K 中说明资本开支主要用途/类别的引导句，连同完整列表及必要相邻说明一起阅读，确认没有漏项；保留每类精确原文、期间语境和可追溯来源。不得以任意同源段落替代实际用途分类。"
    },
    {
      "requirement_id": "req-ev-capex-uses-future-vs-actual",
      "kind": "source_evidence",
      "source_id": "googl-2025-10k",
      "description": "对资本开支用途逐类区分报告期实际披露与未来投资计划，明确哪些只是未来预期；若披露不足则记录具体缺口。不得推断维护性资本开支、自由现金流或 AI 投资回报。"
    }
  ]
}
